INSERT INTO topics (id, label, name, summary, body, thumbnail_url, action_title, action_body, action_image_url) VALUES
    (1, 'hitzeinseln', 'Urbane Hitzeinseln', 'Warum Städte sich stärker aufheizen.', '[{"type":"heading","value":"Was sind Hitzeinseln?"},{"type":"text","value":"Versiegelte Flächen wie Asphalt und Beton speichern tagsüber Wärme und geben sie nachts ab. Dadurch bleiben Innenstädte deutlich wärmer als das Umland."},{"type":"text","value":"Besonders in Hitzewellen kann der Unterschied mehrere Grad betragen und die Gesundheit belasten."}]'::jsonb, 'https://picsum.photos/seed/hitzeinseln/600/400', 'Was kann ich tun?', '[{"type":"text","value":"Schaffe schattige, kühle Orte: begrünte Fassaden, Bäume und entsiegelte Flächen senken die lokale Temperatur spürbar."},{"type":"list","items":["Vorgärten entsiegeln statt schottern","Bäume und Sträucher pflanzen","Helle, reflektierende Materialien nutzen","An heißen Tagen morgens lüften"]}]'::jsonb, 'https://picsum.photos/seed/hitze-aktion/600/360'),
    (2, 'starkregen', 'Starkregen & Überschwemmung', 'Wenn Kanäle an ihre Grenzen kommen.', '[{"type":"heading","value":"Warum überschwemmt es?"},{"type":"text","value":"Bei Starkregen fällt in kurzer Zeit sehr viel Wasser. Versiegelte Böden können es nicht aufnehmen, die Kanalisation läuft über."}]'::jsonb, 'https://picsum.photos/seed/starkregen/600/400', 'Was kann ich tun?', '[{"type":"text","value":"Hilf dem Wasser, zu versickern, statt es schnell abzuleiten."},{"type":"list","items":["Regentonnen und Zisternen nutzen","Flächen entsiegeln","Dach- und Fassadenbegrünung anlegen","Kellerschächte hochwassersicher abdichten"]}]'::jsonb, 'https://picsum.photos/seed/regen-aktion/600/360'),
    (3, 'hitzekuppel', 'Hitzekuppel', 'Hitzekuppeln in Städten – Herausforderungen des Klimawandels und Wege zu einer klimaangepassten Stadt', '[{"type":"heading","value":"Wenn sich die Hitze über der Stadt staut"},{"type":"text","value":"An heißen Sommertagen können sich Städte deutlich stärker aufheizen als ihr Umland. Ein Grund dafür ist das sogenannte Wärmeinsel-Phänomen: Gebäude, Asphalt und Pflasterflächen speichern tagsüber große Mengen Sonnenenergie und geben diese nur langsam wieder ab. Dadurch bleiben die Temperaturen besonders in den Abend- und Nachtstunden hoch."},{"type":"text","value":"Kommt zusätzlich eine stabile Hochdruckwetterlage hinzu, spricht man häufig von einer Hitzekuppel. Dabei wirkt ein Hochdruckgebiet wie eine Art Deckel über der Atmosphäre. Die warme Luft kann kaum aufsteigen oder durch kühlere Luft ersetzt werden. Dadurch sammeln sich Hitze und trockene Luft über einer Region, sodass über mehrere Tage oder sogar Wochen außergewöhnlich hohe Temperaturen auftreten können. Solche Wetterlagen treten zwar auch unabhängig vom Klimawandel auf, doch durch die steigenden Durchschnittstemperaturen werden sie häufiger, intensiver und länger anhaltend."},{"type":"heading","value":"Klimawandel aund Auswirkungen auf das Stadtklima"},{"type":"text","value":"Der Klimawandel führt weltweit zu steigenden\nDurchschnittstemperaturen und häufigeren\nExtremwetterereignissen. Auch in Soest werden längere\nHitzeperioden, mehr heiße Tage über 30 ℃ und tropische\nNachte erwartet. Besonders dicht bebaute Bereiche der\nInnenstadt erwärmen sich starker als das offene Umland, da\nversiegelte Flächen Wärme speichern und gleichzeitig nur\nwenig Verdunstung stattfindet."},{"type":"text","value":"Hohe Temperaturen belasten nicht nur die Gesundheit von\nMenschen - insbesondere von Kindern, älteren Menschen und\nchronisch Erkrankten -, sondern wirken sich auch auf Pflanzen,\nTiere und die städtische Infrastruktur aus. Bäume leiden unter\nTrockenheit, Boden trocknen aus und bei lang anhaltender Hitze\nsteigt der Energiebedarf für Kühlung in Gebäuden. Gleichzeitig\nkönnen warme Nächte den Körper zusätzlich belasten, weil er\nsich nicht ausreichend abkühlen kann."},{"type":"heading","value":"Der Marktplatz in Soest als Beispiel"},{"type":"text","value":"Der Marktplatz in Soest als Beispiel\n\nDer Marktplatz in Soest zeigt beispielhaft, wie historische\nInnenstädte von Hitze betroffen sein können. Große\nPflasterflächen nehmen an sonnigen Tagen viel Wärme auf und\ngeben sie erst langsam wieder ab. Dadurch können sich\nOberflächen und die umgebende Luft deutlich erwärmen."},{"type":"text","value":"Aus diesem Grund spielt die klimaangepasste Gestaltung des\nPlatzes eine immer größere Rolle. Im Zuge der Neugestaltung\nwurden unter anderem zusätzliche Grünflächen, Bäume und\nAufenthaltsbereiche geschaffen. Diese spenden Schatten,\nverbessern die Aufenthaltsqualität und tragen durch\nVerdunstung dazu bei, die Umgebungstemperatur zu senken.\nSolche Maßnahmen helfen, die Auswirkungen sommerlicher\nHitze abzumildern und den historischen Marktplatz auch in\nZukunft als lebendigen Treffpunkt zu erhalten."},{"type":"heading","value":"Maßnahmen für eine klimaangepasste Stadt"},{"type":"text","value":"Städte können mit verschiedenen Maßnahmen dazu beitragen,\ndie Folgen von Hitzeperioden zu verringern. Besonders wichtig\nist der Erhalt und die Neupflanzung von Baumen, da sie\nSchatten spenden und die Luft durch Verdunstung kühlen.\nEbenso tragen Parks, Grunanlagen und begrunte Innenhofe\ndazu bei, sogenannte Kaltluftinseln zu schaffen."},{"type":"text","value":"Auch Wasser spielt eine wichtige Rolle. Brunnen, Wasserspiele,\nTeiche und renaturierte Bäche verbessern das Mikroklima und\nsorgen an heißen Tagen für eine spürbare Abkühlung. Zusätzlich\nhelfen Dach- und Fassadenbegrünungen sowie entsiegelte\nFlächen dabei, Regenwasser zu speichern und die Aufheizung\nvon Gebäuden und Straßen zu reduzieren. Die Stadt Soest\nverfolgt diese Ansätze bereits im Rahmen ihrer\nKlimaanpassungsstrategie und fordert unter anderem\nBegrünungsmaßnahmen sowie den Erhalt von Grünflächen und\nFrischluftschneisen."}]'::jsonb, NULL, NULL, '[{"type":"text","value":"Nicht nur Städte, sondern auch Bürgerinnen und Bürger können\neinen Beitrag leisten. Gärten mit Bäumen, Sträuchern und\nheimischen Pflanzen heizen sich deutlich weniger auf als\nvollständig versiegelte oder geschotterte Flächen. Regenwasser\nkann in Regentonnen gesammelt und zum Gießen von Pflanzen\noder Straßenbäumen genutzt werden. Auch begrünte Dächer\nund Fassaden helfen dabei, Gebäude zu kühlen und\nLebensräume für Insekten zu schaffen."},{"type":"text","value":"An besonders heißen Tagen ist es außerdem wichtig,\nausreichend zu trinken, körperliche Anstrengungen in die\nkühleren Morgen- oder Abendstunden zu verlegen und\nschattige oder klimatisch angenehme Orte aufzusuchen. In\nSoest weist die Stadt auf sogenannte „coole Orte“ hin - dazu\ngehoren Parks, Bereiche am Wasser, Kirchen oder andere\nöffentliche Gebäude mit angenehmen Temperaturen."}]'::jsonb, NULL);
INSERT INTO walk_locations (id, label, name, short_text, body, thumbnail_url, aerial_url, location, station_number, in_klima_quartett) VALUES
    (1, 'wiesenkirche', 'St. Maria zur Wiese', 'Zentraler Platz der Altstadt.', '[{"type":"heading","value":"St. Maria zur Wiese"},{"type":"text","value":"Die Wiesenkirche ist eine der bekanntesten spätgotischen Hallenkirchen in Deutschland und liegt etwas außerhalb des unmittelbaren Marktkerns. Sie wurde im 14. Jahrhundert begonnen und beeindruckt vor allem durch ihre schlanken, hohen Fenster und die filigrane Bauweise."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Im Inneren fällt besonders das Licht auf, das durch die großen Glasfenster in den Raum fällt und eine sehr helle, fast schwebende Atmosphäre erzeugt. Die Kirche gilt als eines der besten Beispiele westfälischer Gotik und ist auch kunsthistorisch sehr bedeutend."}]'::jsonb, 'https://www.baukunst-nrw.de/img/objekte/XL/1115_IMG_20240508_094816~2.jpg', 'https://picsum.photos/seed/marktplatz-air/240/180', ST_GeomFromEWKT('SRID=4326;POINT(8.10936 51.57496)'), 1, false),
    (2, 'rathaus', 'Historisches Rathaus', 'Ort des Westfälischen Friedens.', '{"time":1784622181161,"blocks":[{"id":"2ol2zPkzLf","data":{"text":"Das Soester Rathaus","level":2},"type":"header"},{"id":"FFOJCfL__R","data":{"text":"Hier sitzt die Verwaltung des Kreises Soest."},"type":"paragraph"}],"version":"2.31.2"}'::jsonb, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQk_MqjSbdElKZy9XRoJ8Kv0GkdH2QSsG9aKA&s', 'https://picsum.photos/seed/rathaus-air/240/180', ST_GeomFromEWKT('SRID=4326;POINT(8.10749 51.5719)'), 2, false),
    (3, 'domPetriKirche', 'Dom und Petrikirche', 'Bischofskirche aus dem 13. Jh.', '[{"type":"heading","value":"Architektur"},{"type":"text","value":"Bedeutender Sakralbau mit astronomischer Uhr aus dem 16. Jahrhundert."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/8/86/Soest_st_petri.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Soest%2C_St.-Petri-Kirche_und_St.-Patrokli-Dom_--_2014_--_8756_--_Ausschnitt.jpg/250px-Soest%2C_St.-Petri-Kirche_und_St.-Patrokli-Dom_--_2014_--_8756_--_Ausschnitt.jpg', ST_GeomFromEWKT('SRID=4326;POINT(8.10763 51.57164)'), 3, false),
    (4, 'großerTeich', 'Am Großen Teich', 'Der Große Teich in Soest ist ein zentral gelegener, von Grünanlagen umgebener Stadtteich, der sowohl als Naherholungsgebiet als auch als Lebensraum für verschiedene Tierarten dient. Durch die Wasserfläche und die umliegende Vegetation entsteht dort ein etwas feuchteres und im Sommer oft angenehm kühleres Mikroklima als in der bebauten Innenstadt.', '[{"type":"heading","value":"Vom Quellsumpf zum Großen Teich"},{"type":"text","value":"Der Große Teich im Herzen der Stadt Soest ist weit mehr als ein malerisches Gewässer. Er stellt ein bedeutendes Natur- und Kulturdenkmal dar, dessen Geschichte eng mit der Entstehung und Entwicklung der Stadt verbunden ist. Sein Ursprung liegt in einem ausgedehnten Quellsumpfgebiet, in dem zahlreiche natürliche Quellen aus dem Boden austraten. Diese besondere geologische Situation prägte die Landschaft bereits lange vor der Gründung der mittelalterlichen Stadt."},{"type":"text","value":"Im Laufe des 12. Jahrhunderts wurde das sumpfige Quellgebiet durch gezielte Aufstauungen und bauliche Maßnahmen in einen künstlich geformten Teich umgewandelt. Trotz dieser Veränderungen wird der Große Teich bis heute von mehreren ergiebigen Quellen gespeist. Das Quellwasser tritt ganzjährig mit einer Temperatur von etwa 8 °C aus dem Boden aus. Dadurch bleibt das Wasser auch in den Wintermonaten vergleichsweise warm, sodass der Teich selbst bei länger anhaltendem Frost meist nicht vollständig zufriert."},{"type":"heading","value":"Grundlage für die Entwicklung der Stadt"},{"type":"text","value":"Die Wasserfülle des Gebietes war für die Entwicklung Soests von großer Bedeutung. Bereits im Mittelalter nutzten die Bewohner die natürlichen Ressourcen gezielt für wirtschaftliche Zwecke. Das Wasser des Großen Teichs trieb die Teichsmühle an und unterstützte die Salzgewinnung, die über Jahrhunderte hinweg zu den wichtigsten Wirtschaftszweigen der Stadt gehörte. Darüber hinaus versorgte es Handwerksbetriebe, Haushalte und landwirtschaftliche Flächen mit dem notwendigen Wasser. Der Große Teich war damit ein wesentlicher Faktor für den Wohlstand und die Entwicklung Soests."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"heading","value":"Klimaoase und Lebensraum mitten in der Altstadt"},{"type":"text","value":"Auch heute erfüllt der Teich wichtige Funktionen. Besonders im Zuge des Klimawandels gewinnt seine ökologische Bedeutung zunehmend an Gewicht. Als große Wasserfläche wirkt er temperaturausgleichend und speichert Wärme über längere Zeiträume. An heißen Sommertagen entsteht durch Verdunstung eine kühlende Wirkung, die das unmittelbare Umfeld spürbar entlastet. Gemeinsam mit dem renaturierten Soestbach bildet der Große Teich eine wertvolle „Kaltluftinsel“ innerhalb der Stadt und trägt dazu bei, die Folgen steigender Temperaturen abzumildern. Gleichzeitig hilft das Gewässer dabei, Wasser zurückzuhalten und den natürlichen Wasserhaushalt zu stabilisieren."},{"type":"heading","value":"Natur- und Erholungsraum für Mensch und Tier"},{"type":"text","value":"Darüber hinaus ist der Große Teich ein bedeutender Lebensraum für zahlreiche Tier- und Pflanzenarten. Wasservögel nutzen die ruhigen Wasserflächen als Rast-, Brut- und Nahrungsgebiet. Amphibien finden in den Uferzonen geeignete Lebensbedingungen, während zahlreiche Insektenarten von den vielfältigen Strukturen und Pflanzenbeständen profitieren. Die Verbindung von Wasser, Ufervegetation und angrenzenden Grünflächen schafft ein ökologisch wertvolles Biotop mitten in der Stadt."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Neben seiner historischen und ökologischen Bedeutung besitzt der Große Teich auch einen hohen Erholungswert für die Menschen. Spazierwege, Grünflächen und die besondere Atmosphäre des Gewässers laden zum Verweilen ein. Der Teich verbindet auf einzigartige Weise Natur, Geschichte und modernes Stadtleben und ist damit ein prägendes Element der Soester Altstadt. Als Zeugnis der Stadtgeschichte und zugleich als wichtiger Lebensraum zeigt der Große Teich, wie eng die Entwicklung menschlicher Siedlungen mit natürlichen Ressourcen verknüpft ist und welche Bedeutung diese auch für die Zukunft haben."}]'::jsonb, 'https://www.so-ist-soest.de/de-wAssets/img/tourismus/sehenswertes/sehenswuerdigkeiten/20240430_182821__NI97664.jpg', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10838 51.57359)'), 4, false),
    (5, 'loerBach', 'Am Loerbach', NULL, '[{"type":"heading","value":"Am Loerbach"},{"type":"text","value":"Am Loerbach in Soest ist eine historische Straße und ein Gewässerbereich, der eng mit dem Verlauf des Soestbachs verbunden ist. Der Name geht auf die früher dort ansässigen Lohgerber zurück, die das Wasser des Baches für ihre Arbeit benötigten. Bereits im Mittelalter wurde der Abschnitt wirtschaftlich genutzt, weshalb sich hier ein eigenes Handwerksviertel entwickelte."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Heute ist „Am Loerbach“ ein gut erhaltener Teil der Soester Altstadt mit charakteristischen Fachwerkhäusern aus dem 17. und 18. Jahrhundert. Die Straße liegt direkt am teilweise renaturierten Soestbach und verbindet historische Bebauung mit einem modern gestalteten Bachlauf. Dadurch wirkt der Bereich gleichzeitig sehr altstädtisch und naturnah, was ihn zu einem beliebten Abschnitt bei Spaziergängen durch die Innenstadt macht."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/9/9e/Soest_Loerbach_bridge.jpg', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10811 51.57449)'), 5, false),
    (6, 'soestbach1', 'Am Soestbach 1', NULL, '[{"type":"heading","value":"Am Soestbach (West)"},{"type":"text","value":"Der Soestbach ist ein etwa 13 Kilometer langer Flachlandbach in Nordrhein-Westfalen und entspringt im Bereich der Soester Altstadt. Er durchquert die Stadt in mehreren Abschnitten, wobei er heute teilweise offen sichtbar und teilweise unterirdisch oder verrohrt verläuft. Sein Verlauf prägt die Struktur der Innenstadt, auch wenn er in früheren Zeiten stärker in das Stadtbild eingebunden war."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Besonders im Zentrum spielt der Bach eine wichtige Rolle für die Stadtentwicklung, da er historisch als Wasserquelle und Bestandteil der Befestigungs- und Entwässerungssysteme genutzt wurde. Heute wird er zunehmend wieder freigelegt und renaturiert, wodurch er wieder stärker als naturnahes Element im Stadtbild wahrgenommen wird."}]'::jsonb, 'https://mitwirken-in-soest.de/wp-content/uploads/2024/08/Projekt_8_Renaturierung_Soestbach_2.jpg', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.1018 51.57546)'), 6, false),
    (7, 'soestbach2', 'Am Soestbach 2', NULL, '[{"type":"heading","value":"Am Soestbach (Süd)"},{"type":"text","value":"Im Bereich „Am Loerbach“ zeigt sich der Soestbach als Teil eines historischen Handwerksviertels. Der Name „Loerbach“ geht auf die Lohgerber zurück, die das Bachwasser für das Gerben von Tierhäuten benötigten. Dadurch entwickelte sich entlang des Gewässers schon früh eine gewerbliche Nutzung, die eng mit der Stadtgeschichte verbunden ist."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Heute ist dieser Abschnitt besonders durch Fachwerkbebauung und die Nähe zum Bach geprägt. Der renaturierte Wasserlauf verläuft hier sichtbar entlang der Straße und verbindet historische Stadtstruktur mit einer modernen, naturnahen Gestaltung."}]'::jsonb, 'https://www.soester-anzeiger.de/assets/images/14/196/14196456-1778469301-27bcd672-e59c-4d5a-8d8f-2d960e2171bc-2Rea.jpg', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10585 51.57445)'), 7, false),
    (8, 'bastion', 'Bastion', NULL, '[{"type":"heading","value":"Bastion"},{"type":"text","value":"Die Bastionen in Soest gehören zu den Resten der ehemaligen Stadtbefestigung und sind Teil des größeren Systems aus Wallanlagen, Gräben und Wehranlagen, die die Altstadt im Mittelalter umgaben. Eine Bastion ist dabei ein vorspringender Befestigungsbau, der es ermöglichte, die Stadtmauer seitlich zu verteidigen. In Soest stammen viele dieser Anlagen aus der frühen Neuzeit, als die mittelalterlichen Mauern an neue militärische Anforderungen angepasst wurden."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Heute sind die Bastionen keine militärischen Anlagen mehr, sondern in die grünen Wallanlagen integriert. Sie sind als erhöhte Geländestrukturen oder parkähnliche Bereiche erhalten geblieben und machen den Verlauf der alten Verteidigungsanlagen noch gut nachvollziehbar. Beim Spaziergang entlang der Wälle erkennt man an diesen Stellen besonders gut, wie stark die Stadt früher befestigt war und wie die historische Struktur noch immer das Stadtbild prägt."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Soest_Bastion.JPG/1280px-Soest_Bastion.JPG', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10249 51.56766)'), 8, false),
    (9, 'bergenthalpark', 'Bergenthalpark', NULL, '[{"type":"heading","value":"Bergenthalpark"},{"type":"text","value":"Der Bergenthalpark ist eine der wichtigsten und zugleich ruhigsten Grünanlagen in der Soester Altstadt. Er liegt im Westen der Innenstadt direkt an den historischen Wallanlagen und gilt als die größte innerstädtische Parkfläche innerhalb der alten Stadtmauern. Besonders auffällig ist der alte Baumbestand, der teilweise über 100 Jahre alt ist und dem Park eine sehr geschützte, fast parkartige Waldatmosphäre gibt."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Im Park befindet sich außerdem das Haus Kükelhaus, das eng mit dem Künstler und Pädagogen Hugo Kükelhaus verbunden ist. Er gestaltete hier Teile der Anlage und entwickelte Spiel- und Erfahrungsstationen, die bis heute im Park zu finden sind. Dadurch ist der Bergenthalpark nicht nur ein Ort zur Erholung, sondern auch ein Platz, an dem Natur, Kunst und Sinneserfahrung miteinander verbunden werden und man die besondere Geschichte des Areals gut erkennen kann."}]'::jsonb, 'https://www.so-ist-soest.de/de-wAssets/img/weblication/wThumbnails/4aa62c79b4b1a23g1a0064bbeb7c1784.jpg', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10165 51.57162)'), 9, false),
    (10, 'marktplatz', 'Marktplatz', 'Der Soester Marktplatz - Herz einer historischen Hansestadt', '[{"type":"heading","value":"Der Soester Marktplatz - Herz einer historischen Hansestadt"},{"type":"text","value":"Der Soester Marktplatz bildet seit dem Mittelalter das lebendige Zentrum der Stadt. Bereits im 12. Jahrhundert entwickelte sich hier ein bedeutender Handelsplatz, an dem Kaufleute aus nah und fern ihre Waren anboten. Die gunstige Lage an wichtigen Handelsrouten machte Soest zu einer florierenden Hansestadt, deren wirtschaftliches Leben sich uber Jahrhunderte rund um diesen Platz abspielte. Bis heute ist der Marktplatz von historischen Gebäuden und prächtigen Giebelhäusern umgeben, die die Entwicklung Soests eindrucksvoll widerspiegeln. Besonders charakteristisch sind die Bauwerke aus dem regionaltypischen Grünsandstein, der dem Stadtbild seinen unverwechselbaren Charakter verleiht."},{"alt":"Der Soester Marktplatz mit historischen Gebäuden und Giebelhäusern aus Grünsandstein.","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Soest_Marktplatz_2012.jpg/2560px-Soest_Marktplatz_2012.jpg","type":"image"},{"type":"text","value":"Als offenes Entrée zur Altstadt lädt der Soester Marktplatz dazu ein, Geschichte zu erleben, regionale Traditionen zu entdecken und die besondere Atmosphäre dieser über 1.000 Jahre alten Stadt zu genießen."},{"type":"heading","value":"Natur, Kultur und Leben"},{"type":"text","value":"Der Soester Marktplatz ist das pulsierende Zentrum der Stadt und zugleich ein Ort, an dem Geschichte, Natur und Kultur aufeinandertreffen. Geografisch liegt er inmitten der historischen Altstadt und bildet den Schnittpunkt wichtiger Straßenachsen, die Soest seit dem Mittelalter mit der Umgebung verbinden."},{"type":"text","value":"Biologisch ist der Platz trotz seiner urbanen Lage ein kleiner Lebensraum fur Stadtpflanzen und Vogel. Baume, Pflanzkubel und Wasserstellen bieten Schatten, Nahrung und Rückzugsmöglichkeiten für Tiere, während sie gleichzeitig das Mikroklima verbessern."},{"type":"text","value":"Kulturell ist der Marktplatz Herzstück des öffentlichen Lebens in Soest. Wochenmärkte, Feste wie das Soester Fehde-Spektakel, Weihnachtsmarkt und zahlreiche Konzerte beleben die Fläche das ganze Jahr über. Zahlreiche Cafes, Restaurants und Eisdielen laden zum Verweilen ein und bieten regionale Spezialitäten wie Soester Bier, westfälische Backwaren oder saisonale Gerichte."},{"alt":"Der Soester Marktplatz mit historischen Gebäuden und Giebelhäusern aus Grünsandstein.","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Soest_Marktplatz_2012.jpg/2560px-Soest_Marktplatz_2012.jpg","type":"image"},{"type":"heading","value":"De Hitzekuppel der Soester Altstadt"},{"type":"text","value":"Der Soester Marktplatz ist nicht nur das historische Herz der Stadt, sondern im Sommer auch eine Hitzekuppel : Pflaster und dicht stehende Gebäude speichern die Sonne und lassen die Hitze nachts nur langsam entweichen. Besonders ältere Menschen, Kinder und Kranke spüren diese starke Wärmebelastung."},{"type":"text","value":" In den letzten Jahren wurden gezielt Maßnahmen umgesetzt, um das Mikroklima auf dem Marktplatz zu verbessern. Mobile Bäume und Pflanzgefäße sorgen für Schatten, begrünte Fassaden und Dächer kühlen die Umgebung, und Wasserelemente wie Trinkbrunnen und kleine Fontänen schaffen Frischeinseln. Versiegelte Flächen wurden reduziert, sodass Regenwasser besser versickern kann und Verdunstung zur Kühlung beiträgt. Der Marktplatz wird so zu einem angenehmeren Ort für Besucherinnen, Besucher und die Menschen, die hier arbeiten."}]'::jsonb, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ4L9ZNhcP4tthGlGgmCgNGzPJuttHl1ty5zg&s', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10612 51.57265)'), 10, false),
    (11, 'jakobitor', 'Am Jakobitor', NULL, '[{"type":"heading","value":"Jakobitor"},{"type":"text","value":"Das Jakobitor ist eines der ehemaligen Stadttore der Soester Wallanlage und markierte früher einen wichtigen Zugang zur Altstadt. Es gehörte zur mittelalterlichen Stadtbefestigung, die Soest vollständig umschloss, und wurde strategisch so angelegt, dass Ein- und Ausgänge kontrolliert werden konnten. Heute ist das Tor nicht mehr in seiner ursprünglichen Funktion erhalten, aber der Bereich ist städtebaulich stark aufgewertet und Teil der Wallanlage."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Im Zuge der Sanierungen wurde der Bereich rund um das Jakobitor modern gestaltet und archäologisch untersucht, wobei Fundamente der alten Toranlage wieder sichtbar wurden. Dadurch lässt sich die historische Struktur der Stadtbefestigung heute noch gut nachvollziehen und der Übergang zwischen Altstadt und Wallanlage ist deutlich erkennbar."}]'::jsonb, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ37cxUNDs2_LUsOCQPEcBAMBh4r9eX6PdVQg&s', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSUpHQ3zO6PasVX0tArmjvnxaH8jS4rXxTSqQ&s', ST_GeomFromEWKT('SRID=4326;POINT(8.10147 51.56846)'), 11, false),
    (12, 'rosengarten', 'Rosengarten', NULL, '[{"type":"heading","value":"Rosengarten"},{"type":"text","value":"Der Rosengarten ist eine Grünanlage innerhalb der Soester Wallanlagen und befindet sich auf einem Abschnitt der ehemaligen Stadtbefestigung. Ursprünglich war dieses Gelände Teil des Verteidigungsbereichs der Stadt, später wurden hier private Gärten angelegt, bevor der Bereich nach dem Zweiten Weltkrieg zu einer öffentlichen Parkanlage umgestaltet wurde.."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Heute ist der Rosengarten ein beliebter Aufenthaltsort mit Wegen, Grünflächen und einem guten Blick auf die historischen Wallstrukturen. Besonders interessant ist der erhaltene Bezug zur Stadtgeschichte, da hier noch Spuren der alten Stadtmauer sowie ein Luftschutzstollen aus dem Zweiten Weltkrieg vorhanden sind, die bei Führungen teilweise zugänglich sind."}]'::jsonb, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRIShvEQrnLV_ABw2vTw-Mh0sbLTJavb_VnCw&s', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10413 51.56681)'), 12, false),
    (13, 'schüngel', 'Schüngel', NULL, '[{"type":"heading","value":"Schüngel"},{"type":"text","value":"Der Bereich Schüngel in Soest bezeichnet einen Abschnitt der Wallanlage beziehungsweise der innerstädtischen Grün- und Wegeverbindungen, der eng mit dem historischen Befestigungsring verbunden ist. Der Name ist lokal geprägt und steht für einen Teil der Wege- und Grünstruktur, die entlang der alten Stadtbefestigung verläuft."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Heute ist Schüngel vor allem ein ruhiger Abschnitt innerhalb der Wallanlagen, der als Spazierweg genutzt wird. Wie viele andere Teile des Walls verbindet er historische Strukturen mit moderner Naherholung und zeigt, wie stark die mittelalterliche Stadtform noch im heutigen Stadtbild präsent ist."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Sch%C3%BCngelgasse_1%2C_1%2C_Soest%2C_Landkreis_Soest.jpg/1280px-Sch%C3%BCngelgasse_1%2C_1%2C_Soest%2C_Landkreis_Soest.jpg', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10569 51.56739)'), 13, false),
    (14, 'paulikirche', 'Paulikirche', NULL, '[{"type":"heading","value":"St. Paulikirche"},{"type":"text","value":"Die St. Paulikirche ist eine der bedeutendsten Kirchen in Soest und gehört zu den ältesten Pfarrkirchen Westfalens. Ihre Ursprünge reichen bis ins frühe 13. Jahrhundert zurück, der heutige Bau entwickelte sich im 14. und 15. Jahrhundert aus einer romanischen zu einer gotischen Hallenkirche. Besonders auffällig ist der mächtige Westturm, der das Stadtbild deutlich prägt."},{"alt":"Historische Altstadt Soest","url":"https://www.hso-nrw.de/fileadmin/_processed_/a/0/csm_soest-panorama_95b9c27b9a.jpg","type":"image"},{"type":"text","value":"Im Inneren besitzt die Kirche eine wertvolle Ausstattung mit mittelalterlichen Glasfenstern, einer Renaissance-Kanzel und einem Altar aus der Werkstatt des Conrad von Soest. Seit 2009 wird ein Teil des Kirchenraums zudem als Kolumbarium genutzt, wodurch die Kirche heute sowohl sakraler Ort als auch Erinnerungsstätte ist."}]'::jsonb, 'https://www.so-ist-soest.de/de-wAssets/img/tourismus/sehenswertes/sehenswuerdigkeiten/HPneu-Paulikirche-20221111_161605_NI9_8195.jpg', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.10689 51.56896)'), 14, false),
    (15, 'fh2', 'FH Gebäude 2', NULL, NULL, 'https://www.fh-swf.de/media/neu_np/allgemein_8/bilder_neu/soest_np/hoersaal__mensa__bib_leer/campus-soest_Maibluete_2021-9_hauptnavigation_l.webp', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.11306 51.56184)'), 15, false),
    (16, 'audimax', 'Fachhochschule', NULL, NULL, 'https://www.fh-swf.de/media/neu_np/allgemein_8/bilder_neu/soest_np/hoersaal__mensa__bib_leer/campus-soest_Maibluete_2021-9_hauptnavigation_l.webp', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.11544 51.56023)'), 16, false),
    (17, 'mensa', 'Mensa', NULL, NULL, 'https://www.stwdo.de/media/images/SoestMensa_Teaserbild_QTvtiPU.2e16d0ba.fill-800x450.webp', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.11441 51.56087)'), 17, false),
    (18, 'fh17', 'FH Gebäude 17', NULL, NULL, 'https://www.fh-swf.de/media/neu_np/allgemein_8/bilder_neu/soest_np/hoersaal__mensa__bib_leer/campus-soest_Maibluete_2021-9_hauptnavigation_l.webp', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.11489 51.56157)'), 18, false),
    (19, 'church_mariazurhoehe', 'St. Maria zur Höhe', NULL, NULL, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Soest%2C_Maria_zur_H%C3%B6he%2C_Ansicht_von_Nordosten_%28Lentzestra%C3%9Fe%29.jpg/1280px-Soest%2C_Maria_zur_H%C3%B6he%2C_Ansicht_von_Nordosten_%28Lentzestra%C3%9Fe%29.jpg', NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.111278776916208 51.574046813573744)'), 19, false),
    (20, 'fh6', 'FH gebäude 6', 'Zwischen Schweißen und E-Karts', NULL, NULL, NULL, ST_GeomFromEWKT('SRID=4326;POINT(8.11358038361385 51.56048611229215)'), 20, false);
INSERT INTO routes (id, label, name, short_text, body, thumbnail_url, distance_km, duration_min, route_points, category_id, difficulty) VALUES
    (1, 'altstadt-tour', 'Cooler Walk West', 'Ein Spaziergang durch die Altstadt.', '[{"type":"heading","value":"Was erwartet mich?"},{"type":"text","value":"Die Route startet am Großen Teich, einem ruhigen, fast versteckten Wasserbereich am Rand der Soester Wallanlagen. Schon hier wirkt die Umgebung angenehm entschleunigt: Wasser, Grünflächen und alte Stadtstrukturen liegen dicht beieinander. Es ist ein Einstieg, der nicht laut oder überladen ist, sondern eher langsam in die besondere Mischung aus Natur und Geschichte hineinführt, für die Soest bekannt ist."},{"type":"text","value":"Von dort führt der Weg entlang von Loerbach und Soestbach, zwei Gewässern, die sich wie ein feiner roter Faden durch die Stadt ziehen. Besonders spannend ist, dass der Bach nicht einfach „da ist“, sondern immer wieder auftaucht, verschwindet, renaturiert ist oder von alten Fachwerkhäusern begleitet wird. Dadurch entsteht ein ständiges Wechselspiel zwischen Wasserlauf, Stadtgeschichte und moderner Gestaltung, das die Strecke lebendig und abwechslungsreich macht."},{"type":"text","value":"Im Bergenthalpark wird es dann deutlich ruhiger und grüner. Alte Bäume, weiche Wege und die Nähe zu den Wallanlagen sorgen für eine fast parkartige Rückzugssituation mitten in der Stadt. Gleichzeitig spürt man hier, dass dieser Ort nicht zufällig so aussieht, sondern Teil eines größeren historischen Systems ist, das die ganze Altstadt umgibt."},{"type":"text","value":"Danach öffnet sich die Route wieder stärker zur Stadtgeschichte hin: am Jakobitor, im Rosengarten und entlang der Schüngelgasse wird die alte Stadtbefestigung direkt erlebbar. Man läuft buchstäblich auf dem ehemaligen Wallring, der heute ein grüner Spazierweg ist, aber immer noch klar die mittelalterliche Struktur erkennen lässt. Genau dieser Abschnitt macht den besonderen Reiz aus, weil man gleichzeitig durch Park, Geschichte und Stadtgrenze geht, ohne dass es sich getrennt anfühlt."},{"type":"text","value":"Zum Abschluss verdichtet sich alles im Zentrum: St.-Pauli-Kirche, St.-Patrokli-Dom und Rathaus liegen dicht beieinander und bilden einen starken historischen Kern. Hier wird die ganze Route noch einmal „auf den Punkt gebracht“ – mittelalterliche Kirche, monumentaler Dom und historisches Rathaus stehen nebeneinander und zeigen, wie viel Geschichte auf engem Raum zusammenkommt. Gerade dieser letzte Abschnitt macht den Spaziergang besonders rund, weil er die vorherige Mischung aus Wasser, Wall und Grün in ein klares Stadtzentrum überführt."}]'::jsonb, 'https://picsum.photos/seed/altstadt/600/400', 3.2, 45, ST_GeomFromEWKT('SRID=4326;LINESTRING(8.1091785 51.5732808,8.1091323 51.5733435,8.1086157 51.5734949,8.108225 51.5737951,8.1087684 51.5740637,8.1084811 51.5742872,8.1079824 51.5745261,8.1077395 51.5746311,8.1074864 51.5747029,8.1071631 51.574711,8.1071254 51.5745816,8.1066821 51.574522,8.1065024 51.5745793,8.1056161 51.5744111,8.1049379 51.5743181,8.1046462 51.5743117,8.1045193 51.5742977,8.1046722 51.5740575,8.1047828 51.573824,8.1048254 51.5736808,8.1046783 51.5736712,8.1049381 51.5730112,8.1049551 51.5729509,8.1046791 51.5727215,8.1044591 51.572262,8.1037431 51.572424,8.1033228 51.572454,8.1031601 51.5721172,8.1030183 51.5719625,8.1028215 51.5719648,8.1024837 51.5719274,8.1023371 51.571732,8.102345 51.5715115,8.1028631 51.5716316,8.103629 51.5715359,8.1035932 51.5713878,8.103266 51.5712342,8.1025794 51.5711749,8.1018479 51.5710287,8.1007623 51.5709083,8.1001702 51.5708194,8.1002979 51.5705896,8.1007563 51.5702671,8.1009352 51.5700594,8.1009123 51.5698501,8.1009476 51.5697251,8.1010631 51.5696404,8.1012034 51.56914,8.1012774 51.5689403,8.1014811 51.5685512,8.1015857 51.568405,8.1021688 51.5679083,8.1026877 51.5675654,8.1034831 51.5673108,8.1033676 51.5671649,8.1034472 51.5670832,8.1037681 51.5670328,8.1040616 51.5669502,8.1041571 51.5669244,8.104594 51.5666779,8.105329 51.566384,8.1054811 51.5664863,8.1060525 51.5663035,8.1079179 51.5660578,8.1079782 51.5661916,8.1079705 51.5663078,8.1075646 51.5662939,8.1066691 51.5664373,8.1061711 51.5664984,8.1060971 51.5666313,8.1049869 51.5670276,8.1055239 51.5671003,8.1056076 51.5673316,8.1056849 51.5675889,8.1059545 51.5679358,8.1062322 51.5681627,8.1065127 51.5685175,8.1067839 51.5687368,8.1068788 51.5687764,8.1075092 51.5687111,8.1075451 51.5688899,8.1078931 51.5693748,8.1071876 51.5697655,8.1070988 51.5700617,8.1071611 51.5704805,8.1064778 51.5704942,8.1063775 51.5705839,8.1063057 51.5707349,8.1069054 51.5710097,8.1075487 51.5711284,8.1076527 51.5713732,8.1076138 51.571682,8.1074779 51.5719002)'), 2, NULL),
    (2, 'campustour', 'Campus Tour', NULL, '[{"type":"heading","value":"Campus-Tour an der FH Südwestfalen in Soest"},{"type":"text","value":"Die Campus-Tour an der FH Südwestfalen am Standort Soest beginnt in einer ruhigen, grünen Umgebung am Rand der Stadt. Schon beim ersten Eindruck fällt auf, dass der Campus offen und modern gestaltet ist. Viel Natur, klare Wege und funktionale Gebäude prägen die Atmosphäre und schaffen einen angenehmen Einstieg in das Hochschulumfeld."},{"type":"text","value":"Der Rundgang führt anschließend über zentrale Bereiche des Campus vorbei an Hörsälen, Laboren und Aufenthaltsflächen. Dabei wird schnell deutlich, dass der Standort stark praxisorientiert arbeitet. Technische Studiengänge und angewandte Forschung sind hier nicht nur theoretische Inhalte, sondern direkt im Hochschulalltag sichtbar und greifbar."},{"type":"text","value":"Ein weiterer Abschnitt der Tour zeigt besonders anschaulich die Verbindung von Lehre und Anwendung. In Werkstätten, Laboren und Projektflächen arbeiten Studierende an konkreten Aufgaben und Projekten. Die überschaubare Größe des Campus sorgt dabei für kurze Wege und eine persönliche Lernatmosphäre."},{"type":"text","value":"Zum Abschluss führt die Tour zurück in ruhigere Campusbereiche, in denen sich die Mischung aus moderner Ausstattung und grüner Umgebung noch einmal zusammenfügt. Insgesamt entsteht der Eindruck eines gut strukturierten Studienorts, der Praxisnähe, Übersichtlichkeit und ein angenehmes Umfeld miteinander verbindet."}]'::jsonb, 'https://www.soester-anzeiger.de/assets/images/39/498/39498388-wie-andere-hochschulen-soll-auch-die-soester-fachhochschule-2026-weniger-geld-vom-land-bekommen-3ze9.jpg', 0.75, 15, ST_GeomFromEWKT('SRID=4326;LINESTRING(8.1130929 51.5618269,8.11426 51.5608089,8.1145737 51.5604461,8.1148247 51.5603993,8.1150317 51.5601379,8.1153078 51.5601028,8.1154208 51.5601262,8.1154458 51.5602511,8.1155651 51.5603213,8.1154521 51.5605553,8.1153329 51.5606879,8.1154458 51.5609103,8.1148812 51.5616163)'), NULL, 'leicht'),
    (3, 'coolerWalk', 'Cooler Walk', 'Cooler Walk – Soest entdecken', '[{"type":"text","value":"Der „Cooler Walk“ führt dich auf einem abwechslungsreichen Spaziergang durch die schönsten grünen Oasen und historischen Orte der Stadt Soest. Die Route wurde bewusst über besonders schattige und angenehm kühle Wege geplant und bietet auch an warmen Tagen eine entspannte Möglichkeit, die Stadt zu erkunden. Entdecke den Großen Teich, idyllische Gräften, liebevoll gestaltete Gärten und attraktive Aufenthalts- und Spielbereiche. Auf dem Weg erwarten dich außerdem beeindruckende Sehenswürdigkeiten wie die Paulikirche, der Dom, die Petrikirche und das historische Rathaus. Der Rundweg verbindet Natur, Geschichte und Erholung und lädt dazu ein, Soest auf angenehme Weise aus einer neuen Perspektive kennenzulernen."},{"type":"heading","value":"Cooler Walk – Soest entdecken"}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Soest%2C_Maria_zur_H%C3%B6he%2C_Ansicht_von_Nordosten_%28Lentzestra%C3%9Fe%29.jpg/1280px-Soest%2C_Maria_zur_H%C3%B6he%2C_Ansicht_von_Nordosten_%28Lentzestra%C3%9Fe%29.jpg', 4, 120, ST_GeomFromEWKT('SRID=4326;LINESTRING(8.109366505615185 51.57297165521203,8.110262071469862 51.57252636521753,8.112017380546519 51.572726746254915,8.11237560688781 51.57223692438211,8.114274206500937 51.572170130081076,8.115026481819115 51.571724832234906,8.116531032455384 51.571836157105594,8.116638500357794 51.569208817456314,8.113486108548699 51.5675610863058,8.108829166101827 51.56604690232675,8.106214113806061 51.56620277653502,8.104315514192933 51.5669598722329,8.105103612145257 51.56800642493809,8.10571259692685 51.56938694697675,8.106035000634023 51.569631873927534,8.105318547949992 51.57016625542167,8.10657234014738 51.57050024066601,8.108112713417825 51.57074516161887,8.110477007276046 51.57139085598783,8.110082958299245 51.57196974659004,8.109294860346893 51.572927126408985)'), 2, NULL),
    (7, 'abenteuerWalk', 'Abenteuer Walk', NULL, '[{"type":"heading","value":"Abenteuer im Stadtpark"}]'::jsonb, 'https://europa-kletterwald.de/wp-content/uploads/2018/07/IMG_2992.jpg', 3.3, 60, ST_GeomFromEWKT('SRID=4326;LINESTRING(8.106998751635388 51.57405404477899,8.11251510348552 51.5735897762446,8.113491957459445 51.57026833227235,8.104240575709753 51.56776816059906,8.108033067607664 51.566803771922736)'), 1, NULL),
    (8, 'historischerWalk', 'Historischer Walk', 'Auf den Spuren des frühen Soests', NULL, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSeAR5F9qxR8GP_sDGQRjawlJjIDm0QMDEcGg&s', 4.19, 75, ST_GeomFromEWKT('SRID=4326;LINESTRING(8.093272790032103 51.57688223740081,8.090729733874099 51.573053953338615,8.090334147360181 51.56954148251867,8.09355535182803 51.56652054054604,8.094459549572662 51.566169255196115,8.100562884353508 51.56813641819849,8.099206587736063 51.572527100017226,8.100506371994555 51.575020818452145)'), 3, 'schwer'),
    (9, 'sanfterWalk', 'Sanfter Walk', NULL, NULL, 'https://m.media-amazon.com/images/I/41uiYXNK07L._AC_UF894,1000_QL80_.jpg', 2.91, 45, ST_GeomFromEWKT('SRID=4326;LINESTRING(8.10111293580934 51.56968088904418,8.101477608765805 51.56850503878812,8.103255389427773 51.56737166036012,8.104281032117058 51.56707414384101,8.10391635916065 51.56659244630117,8.10200182614031 51.56738582776484,8.100998975510748 51.56823586396979,8.101682737303321 51.56850503878812,8.101067351689892 51.56962422225956)'), 4, 'mittel'),
    (10, 'kidsWalk', 'Walk mit den Kleinsten', NULL, NULL, 'https://www.hellwegradio.de/externalimages/?source=jpg784/spielplatz-beckstrasse-in-lippstadt_1685311188476.jpg&crop=0x202x735x331&resize=735x331&dt=202508130910080', 2.45, 75, ST_GeomFromEWKT('SRID=4326;LINESTRING(8.12860049398742 51.573902230408294,8.131622960985737 51.57439656387555,8.132139961919421 51.57355619378211,8.133206142086323 51.57355879897017,8.134195953387575 51.57400046236714,8.13477968825569 51.57449732855932,8.135194534488136 51.57527323475827,8.135892478333858 51.575935703261536,8.13565137045228 51.57633791156775,8.134915356921027 51.57669279829375,8.134395071493543 51.576669139264936,8.134496590601117 51.57636945716669,8.134128583835036 51.57624327463935,8.134674249039477 51.57547828556821,8.134750388370179 51.57513916258273,8.134318932162756 51.574878903691996,8.133874786065945 51.57466596349076,8.133265671418258 51.57471328362186,8.132770765767617 51.57497354346094,8.132593107329285 51.575091842895375,8.131669612652246 51.57500108058804)'), 5, 'leicht');
