INSERT INTO warning_tips (id, warning_id, sort, heading, text, icon) VALUES
    (1, 1, 1, 'AUSREICHEND TRINKEN', 'Trinke regelmäßig über den Tag verteilt - am besten Wasser oder ungesüßte Getränke.', 'water_drop'),
    (2, 1, 2, 'SONNE UND HITZE MEIDEN', 'Meide die Mittagssonne zwischen 11 und 17 Uhr und halte dich möglichst im Schatten auf.', 'sunny'),
    (3, 1, 3, 'ANSTRENGUNG REDUZIEREN', 'Verlege körperliche anstrengende Tätigkeiten in die kühleren Morgen- oder Abendstunden.', 'sports_gymnastics'),
    (4, 1, 4, 'AUF ANDERE ACHTEN', 'Schaue nach älteren, kranken oder alleinstehenden Menschen in deinem Umfeld und biete Unterstützung an.', 'elderly'),
    (5, 1, 5, 'TIERE SCHÜTZEN', 'Sorge für ausreichend Wasser und Schatten. Lasse deine Tiere niemals im Auto zurück.', 'pets'),
    (6, 1, 6, 'KÜHL HALTEN', 'Lüfte früh morgens oder spät abends. Schließe tagsüber die Fenster und dunkle die Räume ab.', 'ac_unit');
